{
  "name": "LaunchLens: Startup Idea Validator",
  "description": "An AI-powered web app to validate startup ideas. It provides a VC-like analysis on problem pain, market size, monetization, competitive moat, and feasibility, giving a final score and a clear verdict."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useCallback } from 'react';
import { Header } from './components/Header';
import { IdeaForm } from './components/IdeaForm';
import { ResultsDisplay } from './components/ResultsDisplay';
import { Loader } from './components/Loader';
import { validateStartupIdea } from './services/geminiService';
import { type ValidationResult, type BusinessModel } from './types';

const App: React.FC = () => {
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [result, setResult] = useState<ValidationResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleValidate = useCallback(async (idea: string, businessModel: BusinessModel) => {
    if (!idea.trim()) {
      setError('Please describe your startup idea.');
      return;
    }

    setIsLoading(true);
    setResult(null);
    setError(null);

    try {
      const validationResult = await validateStartupIdea(idea, businessModel);
      setResult(validationResult);
    } catch (e) {
      console.error(e);
      setError('Failed to validate idea. The AI may be busy. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }, []);

  return (
    <div className="min-h-screen bg-black text-gray-200 antialiased">
      <div className="container mx-auto px-4 py-8 md:py-16 max-w-3xl">
        <Header />
        <main>
          <IdeaForm onValidate={handleValidate} isLoading={isLoading} />

          {error && (
            <div className="mt-8 text-center bg-red-900/50 border border-red-500/50 text-red-300 p-4 rounded-xl">
              <p>{error}</p>
            </div>
          )}

          {isLoading && <Loader />}

          {result && (
            <div className="mt-12 animate-fade-in">
              <ResultsDisplay result={result} />
            </div>
          )}
        </main>
        <footer className="text-center mt-16 text-zinc-600 text-sm">
          <p>&copy; {new Date().getFullYear()} LaunchLens. AI-powered analysis.</p>
        </footer>
      </div>
    </div>
  );
};

export default App;

export type BusinessModel = 'B2B' | 'B2C';

export interface ScoreDetail {
  score: number;
  reasoning: string;
}

export interface Scores {
  problemPain: ScoreDetail;
  tam: ScoreDetail;
  monetization: ScoreDetail;
  moat: ScoreDetail;
  feasibility: ScoreDetail;
}

export type RiskLevel = 'Low' | 'Medium' | 'High';
export type Verdict = 'Strong idea' | 'Promising but risky' | 'Not viable';

export interface ValidationResult {
  scores: Scores;
  summary: string;
  strengths: string[];
  risks: string[];
  verdict: Verdict;
  riskLevel: RiskLevel;
}

import { GoogleGenAI, Type } from "@google/genai";
import { type ValidationResult, type BusinessModel } from '../types';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

const responseSchema = {
  type: Type.OBJECT,
  properties: {
    scores: {
      type: Type.OBJECT,
      properties: {
        problemPain: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER, description: "Score from 1-10 for problem pain." },
            reasoning: { type: Type.STRING, description: "Brief reasoning for the score." }
          },
          required: ["score", "reasoning"]
        },
        tam: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER, description: "Score from 1-10 for Target Market Size (TAM)." },
            reasoning: { type: Type.STRING, description: "Brief reasoning for the score." }
          },
          required: ["score", "reasoning"]
        },
        monetization: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER, description: "Score from 1-10 for Monetization Viability." },
            reasoning: { type: Type.STRING, description: "Brief reasoning for the score." }
          },
          required: ["score", "reasoning"]
        },
        moat: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER, description: "Score from 1-10 for Competitive Moat." },
            reasoning: { type: Type.STRING, description: "Brief reasoning for the score." }
          },
          required: ["score", "reasoning"]
        },
        feasibility: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER, description: "Score from 1-10 for Execution Feasibility." },
            reasoning: { type: Type.STRING, description: "Brief reasoning for the score." }
          },
          required: ["score", "reasoning"]
        }
      },
      required: ["problemPain", "tam", "monetization", "moat", "feasibility"]
    },
    summary: { type: Type.STRING, description: "A 2-3 line AI summary of the idea's potential." },
    strengths: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Bullet points of key strengths." },
    risks: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Bullet points of key risks and concerns." },
    verdict: { type: Type.STRING, description: "Final verdict: 'Strong idea', 'Promising but risky', or 'Not viable'." },
    riskLevel: { type: Type.STRING, description: "Overall risk level: 'Low', 'Medium', or 'High'." }
  },
  required: ["scores", "summary", "strengths", "risks", "verdict", "riskLevel"]
};

const systemInstruction = `You are 'LaunchLens AI', a seasoned early-stage venture capitalist. Your analysis is sharp, direct, practical, and avoids buzzwords. You evaluate startup ideas on 5 criteria: Problem Pain, Target Market Size (TAM), Monetization Viability, Competitive Moat, and Execution Feasibility. Be realistic and investor-like. If execution is very hard or regulated, reduce the score. If an idea is hype with no real problem, score it low. Balance opportunity vs. risk. You MUST return your analysis ONLY in the provided JSON format. Do not add any text, markdown, or explanations outside the JSON structure.`;


export const validateStartupIdea = async (idea: string, businessModel: BusinessModel): Promise<ValidationResult> => {
  const prompt = `Idea Description: "${idea}"\nBusiness Model: "${businessModel}"\n\nAnalyze this startup idea and provide your evaluation.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema,
        temperature: 0.3,
      },
    });

    const jsonText = response.text.trim();
    const result = JSON.parse(jsonText);

    // Basic validation to ensure the parsed object matches the expected structure
    if (!result.scores || !result.summary) {
        throw new Error("Invalid JSON structure received from API.");
    }

    return result as ValidationResult;
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    throw new Error("Failed to get validation from AI service.");
  }
};

import React, { useState } from 'react';
import { type BusinessModel } from '../types';

interface IdeaFormProps {
  onValidate: (idea: string, businessModel: BusinessModel) => void;
  isLoading: boolean;
}

export const IdeaForm: React.FC<IdeaFormProps> = ({ onValidate, isLoading }) => {
  const [idea, setIdea] = useState<string>('');
  const [businessModel, setBusinessModel] = useState<BusinessModel>('B2C');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onValidate(idea, businessModel);
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      <div>
        <label htmlFor="startup-idea" className="block text-sm font-medium text-zinc-400 mb-2">
          Describe your Startup Idea
        </label>
        <textarea
          id="startup-idea"
          rows={6}
          value={idea}
          onChange={(e) => setIdea(e.target.value)}
          placeholder="Explain the problem, solution, and who it’s for…"
          className="w-full bg-zinc-900 border border-zinc-700 rounded-xl p-4 text-gray-200 placeholder-zinc-500 focus:ring-2 focus:ring-cyan-500 focus:border-cyan-500 transition-shadow duration-200"
          required
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-zinc-400 mb-2">
          Business Model
        </label>
        <div className="flex space-x-3">
          {(['B2B', 'B2C'] as BusinessModel[]).map((model) => (
            <button
              key={model}
              type="button"
              onClick={() => setBusinessModel(model)}
              className={`px-6 py-2 rounded-full text-sm font-semibold transition-all duration-200 ${
                businessModel === model
                  ? 'bg-cyan-500 text-black shadow-[0_0_15px_rgba(56,189,248,0.3)]'
                  : 'bg-zinc-800 text-zinc-300 hover:bg-zinc-700'
              }`}
            >
              {model}
            </button>
          ))}
        </div>
      </div>

      <div className="pt-2">
        <button
          type="submit"
          disabled={isLoading}
          className="w-full flex justify-center items-center bg-cyan-500 text-black font-bold py-3 px-6 rounded-xl text-lg hover:bg-cyan-400 transition-all duration-300 ease-in-out disabled:bg-zinc-700 disabled:text-zinc-400 disabled:cursor-not-allowed group"
        >
          <span className="group-hover:scale-105 transition-transform duration-300">
            {isLoading ? 'Analyzing...' : 'Validate Idea'}
          </span>
        </button>
      </div>
    </form>
  );
};

import React from 'react';
import { ScoreGauge } from './ScoreGauge';
import { SummaryCard } from './SummaryCard';
import { type ValidationResult, type Scores } from '../types';

interface ResultsDisplayProps {
  result: ValidationResult;
}

const scoreKeyToLabel: Record<keyof Scores, string> = {
  problemPain: 'Problem Pain',
  tam: 'Target Market Size',
  monetization: 'Monetization',
  moat: 'Competitive Moat',
  feasibility: 'Execution Feasibility',
};

export const ResultsDisplay: React.FC<ResultsDisplayProps> = ({ result }) => {
  const scores = Object.values(result.scores).map(s => s.score);
  const finalScore = scores.reduce((a, b) => a + b, 0) / scores.length;

  return (
    <div className="space-y-8">
        <SummaryCard result={result} finalScore={finalScore} />

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {(Object.keys(result.scores) as Array<keyof Scores>).map(key => (
                <div key={key} className="bg-zinc-900 p-6 rounded-2xl border border-zinc-800">
                    <h3 className="text-lg font-semibold text-white mb-3">{scoreKeyToLabel[key]}</h3>
                    <div className="flex items-center gap-4">
                        <ScoreGauge score={result.scores[key].score} />
                        <p className="text-zinc-400 text-sm flex-1">{result.scores[key].reasoning}</p>
                    </div>
                </div>
            ))}
        </div>
    </div>
  );
};

import React from 'react';

interface ScoreGaugeProps {
  score: number;
}

export const ScoreGauge: React.FC<ScoreGaugeProps> = ({ score }) => {
  const getScoreColor = (s: number) => {
    if (s >= 8) return 'text-cyan-400';
    if (s >= 5) return 'text-yellow-400';
    return 'text-red-400';
  };

  return (
    <div className="flex-shrink-0 flex items-center justify-center w-20 h-20 bg-black rounded-full border-2 border-zinc-800">
      <div className={`text-3xl font-bold ${getScoreColor(score)}`}>
        {score.toFixed(0)}
      </div>
    </div>
  );
};

import React from 'react';
import { type ValidationResult, type RiskLevel, type Verdict } from '../types';

interface SummaryCardProps {
  result: ValidationResult;
  finalScore: number;
}

const Tag: React.FC<{ text: string, color: 'cyan' | 'yellow' | 'red' | 'gray' }> = ({ text, color }) => {
  const colorClasses = {
    cyan: 'bg-cyan-900/50 border-cyan-500/50 text-cyan-300',
    yellow: 'bg-yellow-900/50 border-yellow-500/50 text-yellow-300',
    red: 'bg-red-900/50 border-red-500/50 text-red-300',
    gray: 'bg-zinc-800 border-zinc-700 text-zinc-300'
  };
  return (
    <span className={`inline-block px-3 py-1 text-sm font-medium rounded-full border ${colorClasses[color]}`}>
      {text}
    </span>
  );
};

const getVerdictColor = (verdict: Verdict) => {
    switch (verdict) {
        case 'Strong idea': return 'cyan';
        case 'Promising but risky': return 'yellow';
        case 'Not viable': return 'red';
        default: return 'gray';
    }
}

const getRiskColor = (risk: RiskLevel) => {
    switch (risk) {
        case 'Low': return 'cyan';
        case 'Medium': return 'yellow';
        case 'High': return 'red';
        default: return 'gray';
    }
}

export const SummaryCard: React.FC<SummaryCardProps> = ({ result, finalScore }) => {
  return (
    <div className="bg-zinc-900 p-6 md:p-8 rounded-2xl border border-zinc-800">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
        <div>
          <h2 className="text-2xl font-bold text-white mb-1">Validation Report</h2>
          <p className="text-zinc-400">{result.summary}</p>
        </div>
        <div className="flex-shrink-0 text-center md:text-right">
           <div className="text-zinc-400 text-sm">Final Score</div>
           <div className="text-5xl font-bold text-cyan-400" style={{textShadow: '0 0 10px rgba(56, 189, 248, 0.3)'}}>{finalScore.toFixed(1)}</div>
           <div className="text-zinc-400 text-sm">out of 10</div>
        </div>
      </div>

      <div className="flex flex-wrap gap-4 mb-8">
        <Tag text={result.verdict} color={getVerdictColor(result.verdict)} />
        <Tag text={`Risk: ${result.riskLevel}`} color={getRiskColor(result.riskLevel)} />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div>
          <h3 className="text-lg font-semibold text-white mb-3 flex items-center gap-2">
            <CheckIcon /> Strengths
          </h3>
          <ul className="space-y-2 list-inside text-zinc-300">
            {result.strengths.map((item, index) => (
              <li key={index} className="flex items-start">
                <span className="text-cyan-400 mr-2 mt-1">&#8227;</span>
                <span>{item}</span>
                </li>
            ))}
          </ul>
        </div>
        <div>
          <h3 className="text-lg font-semibold text-white mb-3 flex items-center gap-2">
            <AlertIcon /> Risks & Concerns
          </h3>
          <ul className="space-y-2 list-inside text-zinc-300">
            {result.risks.map((item, index) => (
              <li key={index} className="flex items-start">
                <span className="text-yellow-400 mr-2 mt-1">&#8227;</span>
                <span>{item}</span>
                </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
};

const CheckIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-cyan-400"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path><polyline points="22 4 12 14.01 9 11.01"></polyline></svg>
);

const AlertIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-yellow-400"><path d="m21.73 18-8-14a2 2 0 0 0-3.46 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"></path><line x1="12" x2="12" y1="9" y2="13"></line><line x1="12" x2="12.01" y1="17" y2="17"></line></svg>
)

import React from 'react';

export const Loader: React.FC = () => {
  return (
    <div className="flex justify-center items-center py-12">
      <div className="w-12 h-12 border-4 border-zinc-700 border-t-cyan-400 rounded-full animate-spin"></div>
    </div>
  );
};

{
  "name": "LaunchLens: Startup Idea Validator",
  "description": "An AI-powered web app to validate startup ideas. It provides a VC-like analysis on problem pain, market size, monetization, competitive moat, and feasibility, giving a final score and a clear verdict.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React, { useState, useCallback } from 'react';
import { Header } from './components/Header';
import { IdeaForm } from './components/IdeaForm';
import { ResultsDisplay } from './components/ResultsDisplay';
import { Loader } from './components/Loader';
import { VoiceAssistant } from './components/VoiceAssistant';
import { validateStartupIdea } from './services/geminiService';
import { type ValidationResult, type BusinessModel } from './types';

const App: React.FC = () => {
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [result, setResult] = useState<ValidationResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Lifted state to allow voice assistant to populate the form
  const [idea, setIdea] = useState<string>('');
  const [businessModel, setBusinessModel] = useState<BusinessModel>('B2C');
  const [isVoiceMode, setIsVoiceMode] = useState<boolean>(false);

  const handleValidate = useCallback(async (ideaToValidate: string, modelToValidate: BusinessModel) => {
    if (!ideaToValidate.trim()) {
      setError('Please describe your startup idea.');
      return;
    }

    setIsLoading(true);
    setResult(null);
    setError(null);

    try {
      const validationResult = await validateStartupIdea(ideaToValidate, modelToValidate);
      setResult(validationResult);
    } catch (e) {
      console.error(e);
      let errorMessage = 'Failed to validate idea. The AI may be busy. Please try again.';
      if (e instanceof Error) {
        if (e.message.toLowerCase().includes('api key not valid')) {
            errorMessage = 'Your API key is invalid. Please check your configuration.';
        } else if (e.message.toLowerCase().includes('quota')) {
            errorMessage = 'You have exceeded your API quota. Please check your billing or try again later.';
        } else if (e.message.toLowerCase().includes("invalid json")) {
            errorMessage = "The AI returned an invalid response. Let's try that again."
        }
      }
      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleVoiceClose = useCallback((transcript?: string) => {
    setIsVoiceMode(false);
    if (transcript && transcript.trim()) {
      setIdea(transcript);
      // Automatically validate the idea after the conversation
      handleValidate(transcript, businessModel);
    }
  }, [businessModel, handleValidate]);

  return (
    <div className="min-h-screen bg-black text-gray-200 antialiased">
      <div className="container mx-auto px-4 py-8 md:py-16 max-w-3xl">
        <Header onVoiceClick={() => setIsVoiceMode(true)} />
        <main>
          <IdeaForm
            idea={idea}
            setIdea={setIdea}
            businessModel={businessModel}
            setBusinessModel={setBusinessModel}
            onValidate={() => handleValidate(idea, businessModel)}
            isLoading={isLoading}
          />

          {error && (
            <div className="mt-8 text-center bg-red-900/50 border border-red-500/50 text-red-300 p-4 rounded-xl">
              <p>{error}</p>
            </div>
          )}

          {isLoading && <Loader />}

          {result && !isVoiceMode && (
            <div className="mt-12 animate-fade-in">
              <ResultsDisplay result={result} />
            </div>
          )}
        </main>

        {isVoiceMode && <VoiceAssistant onClose={handleVoiceClose} />}

        <footer className="text-center mt-16 text-zinc-600 text-sm">
          <p>&copy; {new Date().getFullYear()} LaunchLens. AI-powered analysis.</p>
        </footer>
      </div>
    </div>
  );
};

export default App;

import React from 'react';

