    strokeLinecap="round"
    strokeLinejoin="round"
    className="w-8 h-8 md:w-10 md:h-10 text-cyan-400"
  >
    <circle cx="11" cy="11" r="8"></circle>
    <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
    <line x1="11" y1="8" x2="11" y2="14"></line>
    <line x1="8" y1="11" x2="14" y2="11"></line>
  </svg>
);

const MicIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="w-6 h-6"><path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3Z"></path><path d="M19 10v2a7 7 0 0 1-14 0v-2"></path><line x1="12" x2="12" y1="19" y2="22"></line></svg>
);


export const Header: React.FC<{ onVoiceClick: () => void }> = ({ onVoiceClick }) => {
  return (
    <header className="text-center mb-10 md:mb-12 relative">
      <div className="flex justify-center items-center gap-4 mb-4">
        <LensIcon />
        <h1 className="text-4xl md:text-5xl font-bold tracking-tight text-white">
          LaunchLens
        </h1>
      </div>
      <p className="text-lg md:text-xl text-zinc-400">
        Focus your vision. Validate your startup idea with AI.
      </p>
      <button 
        onClick={onVoiceClick} 
        aria-label="Start voice conversation"
        className="absolute top-0 right-0 p-3 text-zinc-400 hover:text-cyan-400 transition-colors bg-zinc-900 rounded-full border border-zinc-700 hover:border-cyan-500/50"
      >
        <MicIcon />
      </button>
    </header>
  );
};

import React from 'react';
import { type BusinessModel } from '../types';

interface IdeaFormProps {
  idea: string;
  setIdea: (idea: string) => void;
  businessModel: BusinessModel;
  setBusinessModel: (model: BusinessModel) => void;
  onValidate: () => void;
  isLoading: boolean;
}

export const IdeaForm: React.FC<IdeaFormProps> = ({ idea, setIdea, businessModel, setBusinessModel, onValidate, isLoading }) => {

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onValidate();
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      <div>
        <label htmlFor="startup-idea" className="block text-sm font-medium text-zinc-400 mb-2">
          Describe your Startup Idea
        </label>
        <textarea
          id="startup-idea"
          rows={6}
          value={idea}
          onChange={(e) => setIdea(e.target.value)}
          placeholder="Explain the problem, solution, and who it’s for…"
          className="w-full bg-zinc-900 border border-zinc-700 rounded-xl p-4 text-gray-200 placeholder-zinc-500 focus:ring-2 focus:ring-cyan-500 focus:border-cyan-500 transition-shadow duration-200"
          required
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-zinc-400 mb-2">
          Business Model
        </label>
        <div className="flex space-x-3">
          {(['B2B', 'B2C'] as BusinessModel[]).map((model) => (
            <button
              key={model}
              type="button"
              onClick={() => setBusinessModel(model)}
              className={`px-6 py-2 rounded-full text-sm font-semibold transition-all duration-200 ${
                businessModel === model
                  ? 'bg-cyan-500 text-black shadow-[0_0_15px_rgba(56,189,248,0.3)]'
                  : 'bg-zinc-800 text-zinc-300 hover:bg-zinc-700'
              }`}
            >
              {model}
            </button>
          ))}
        </div>
      </div>

      <div className="pt-2">
        <button
          type="submit"
          disabled={isLoading}
          className="w-full flex justify-center items-center bg-cyan-500 text-black font-bold py-3 px-6 rounded-xl text-lg hover:bg-cyan-400 transition-all duration-300 ease-in-out disabled:bg-zinc-700 disabled:text-zinc-400 disabled:cursor-not-allowed group"
        >
          <span className="group-hover:scale-105 transition-transform duration-300">
            {isLoading ? 'Analyzing...' : 'Validate Idea'}
          </span>
        </button>
      </div>
    </form>
  );
};

export function encode(bytes: Uint8Array): string {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveSession, LiveServerMessage, Modality, Blob } from '@google/genai';
import { encode, decode, decodeAudioData } from '../utils/audio';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable not set");
}
const ai = new GoogleGenAI({ apiKey: API_KEY });

type TranscriptEntry = {
    speaker: 'user' | 'ai';
    text: string;
};

type VoiceStatus = 'idle' | 'connecting' | 'listening' | 'speaking' | 'error';

const StatusIndicator: React.FC<{ status: VoiceStatus }> = ({ status }) => {
    let text = 'Connecting...';
    let colorClass = 'bg-yellow-500';

    switch (status) {
        case 'listening':
            text = 'Listening...';
            colorClass = 'bg-cyan-500 animate-pulse';
            break;
        case 'speaking':
            text = 'AI is speaking...';
            colorClass = 'bg-purple-500';
            break;
        case 'error':
            text = 'Connection Error';
            colorClass = 'bg-red-500';
            break;
    }

    return (
        <div className="flex items-center justify-center gap-3 text-zinc-300">
