const Tag: React.FC<{ text: string, color: 'cyan' | 'yellow' | 'red' | 'gray' }> = ({ text, color }) => {
  const colorClasses = {
    cyan: 'bg-cyan-900/50 border-cyan-500/50 text-cyan-300',
    yellow: 'bg-yellow-900/50 border-yellow-500/50 text-yellow-300',
    red: 'bg-red-900/50 border-red-500/50 text-red-300',
    gray: 'bg-zinc-800 border-zinc-700 text-zinc-300'
  };
  return (
    <span className={`inline-block px-3 py-1 text-sm font-medium rounded-full border ${colorClasses[color]}`}>
      {text}
    </span>
  );
};

const getVerdictColor = (verdict: Verdict) => {
    switch (verdict) {
        case 'Proceed': return 'cyan';
        case 'Proceed with Caution': return 'yellow';
        case 'Do Not Pursue': return 'red';
        default: return 'gray';
    }
}

const getRiskColor = (risk: RiskLevel) => {
    switch (risk) {
        case 'Low': return 'cyan';
        case 'Medium': return 'yellow';
        case 'High': return 'red';
        default: return 'gray';
    }
}

