import { GoogleGenAI, Type } from "@google/genai";
import { type ValidationResult } from '../types';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

const responseSchema = {
    type: Type.OBJECT,
    properties: {
        idea_summary: { type: Type.STRING },
        market_research: {
            type: Type.OBJECT,
            properties: {
                market_demand: { type: Type.STRING },
                problem_pain_points: { type: Type.STRING },
                competition: { type: Type.ARRAY, items: { type: Type.STRING } },
                suggested_usps: { type: Type.ARRAY, items: { type: Type.STRING } },
            },
            required: ["market_demand", "problem_pain_points", "competition", "suggested_usps"]
        },
        execution_foundations: {
            type: Type.OBJECT,
            properties: {
                first_3_steps: { type: Type.ARRAY, items: { type: Type.STRING } },
                brand_building_basics: { type: Type.STRING },
                mvp_suggestion: { type: Type.STRING },
                market_validation_codes: { type: Type.ARRAY, items: { type: Type.STRING } },
            },
            required: ["first_3_steps", "brand_building_basics", "mvp_suggestion", "market_validation_codes"]
        },
        branding_boost: {
            type: Type.OBJECT,
            properties: {
                name_suggestions: { type: Type.ARRAY, items: { type: Type.STRING } },
                tagline_options: { type: Type.ARRAY, items: { type: Type.STRING } },
                brand_story: { type: Type.STRING },
                logo_concept: { type: Type.STRING },
            },
            required: ["name_suggestions", "tagline_options", "brand_story", "logo_concept"]
        },
        historical_comparison: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    company_name: { type: Type.STRING },
                    outcome: { type: Type.STRING },
                    lesson: { type: Type.STRING },
                },
                required: ["company_name", "outcome", "lesson"]
            }
        },
        shark_tank_simulation: {
            type: Type.OBJECT,
            properties: {
                sharks: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            name: { type: Type.STRING },
                            reaction: { type: Type.STRING },
                            score: { type: Type.NUMBER },
                            decision: { type: Type.STRING },
                            offer: { type: Type.STRING },
                            focus_area: { type: Type.STRING },
                        },
                        required: ["name", "reaction", "score", "decision", "focus_area"]
                    }
                },
                deal_likelihood: { type: Type.STRING },
            },
            required: ["sharks", "deal_likelihood"]
        },
        pivoted_ideas: { type: Type.ARRAY, items: { type: Type.STRING } },
        shareable_summary: { type: Type.STRING },
    },
    required: ["idea_summary", "market_research", "execution_foundations", "branding_boost", "historical_comparison", "shark_tank_simulation", "shareable_summary"]
};

const systemInstruction = `You are BuildIT — the ultimate AI co-founder for early-stage startup ideas.

Tagline: "Validate fast. Build smart. Launch strong."

Your mission is to help founders turn raw ideas into viable startups with brutal honesty, creativity, and actionable steps. Always be encouraging yet realistic — founders need truth wrapped in motivation.

When a user shares a startup idea, respond in the exact structured JSON format provided. Use clear headings, short paragraphs, and emojis for readability in your text content.

You MUST return your analysis ONLY in the provided JSON format. Do not add any text, markdown, or explanations outside the JSON structure.`;


export const validateStartupIdea = async (idea: string): Promise<ValidationResult> => {
  const prompt = `Here is the startup idea: "${idea}"\n\nPlease analyze it using your framework and return the structured JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema,
        temperature: 0.5,
      },
    });

    const jsonText = response.text.trim();
    const result = JSON.parse(jsonText);

    if (!result.idea_summary || !result.shark_tank_simulation) {
        throw new Error("Invalid JSON structure received from API.");
    }

    return result as ValidationResult;
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    if(error instanceof Error && error.message.includes('JSON')){
        throw new Error("Invalid JSON structure received from API.");
    }
    throw new Error("Failed to get validation from AI service.");
  }
};

