                <ul className="list-disc list-inside space-y-1">{result.branding_boost.tagline_options.map((tag, i) => <li key={i}>"{tag}"</li>)}</ul>
            </div>
             <div>
                <h3 className="font-semibold text-white mb-1">Short Brand Story</h3>
                <p>{result.branding_boost.brand_story}</p>
            </div>
             <div>
                <h3 className="font-semibold text-white mb-1">Logo Concept Description</h3>
                <p>{result.branding_boost.logo_concept}</p>
            </div>
        </Section>

        <Section title="Historical 'What If' Comparison" emoji="🏛️">
            {result.historical_comparison.map((comp, i) => (
                <div key={i} className="border-t border-zinc-800 pt-4 first:pt-0 first:border-none">
                    <h3 className="font-semibold text-white">{comp.company_name} <span className={`text-sm font-normal ${comp.outcome === 'Success' ? 'text-green-400' : 'text-red-400'}`}>({comp.outcome})</span></h3>
                    <p>{comp.lesson}</p>
                </div>
            ))}
        </Section>

        <Section title="Shark Tank Simulation" emoji="🦈">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {result.shark_tank_simulation.sharks.map(shark => <SharkCard key={shark.name} shark={shark}/>)}
            </div>
            <div className="text-center mt-6">
                <h3 className="text-lg font-bold text-white">Overall Deal Likelihood: <span className="text-cyan-400">{result.shark_tank_simulation.deal_likelihood}</span></h3>
            </div>
        </Section>

        {result.pivoted_ideas && result.pivoted_ideas.length > 0 && (
             <Section title="Pivoted Ideas" emoji="🧭">
                <p>Your initial idea has some critical flaws. Here are a few alternative directions that might solve a similar problem more effectively:</p>
                <ul className="list-disc list-inside space-y-2 font-semibold">{result.pivoted_ideas.map((idea, i) => <li key={i}>{idea}</li>)}</ul>
             </Section>
        )}

        <ShareableSummary summary={result.shareable_summary} />
    </div>
  );
};

