import React from 'react';

interface IdeaFormProps {
  idea: string;
  setIdea: (idea: string) => void;
  onValidate: () => void;
  isLoading: boolean;
}

export const IdeaForm: React.FC<IdeaFormProps> = ({ idea, setIdea, onValidate, isLoading }) => {

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onValidate();
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-8">
      <div>
        <label htmlFor="startup-idea" className="block text-sm font-medium text-zinc-500 mb-2 uppercase tracking-wide">
          What are we building?
        </label>
        <textarea
          id="startup-idea"
          rows={6}
          value={idea}
          onChange={(e) => setIdea(e.target.value)}
          placeholder="e.g. Uber for dog walking but exclusively for corgis..."
          className="w-full bg-black border border-zinc-800 rounded-sm p-4 text-white placeholder-zinc-700 focus:ring-1 focus:ring-white focus:border-white transition-all duration-200 font-light"
          required
        />
      </div>

      <div>
        <button
          type="submit"
          disabled={isLoading}
          className="w-full flex justify-center items-center bg-white text-black font-bold py-4 px-6 rounded-sm text-lg hover:bg-zinc-200 transition-all duration-300 ease-in-out disabled:bg-zinc-800 disabled:text-zinc-600 disabled:cursor-not-allowed tracking-tight"
        >
          {isLoading ? 'ANALYZING...' : 'VALIDATE IDEA'}
        </button>
      </div>
    </form>
  );
};

export interface MarketResearch {
  market_demand: string;
  problem_and_pain_points: string;
  competition: string;
  suggested_usps: string[];
}

export interface ExecutionFoundations {
  first_3_steps: string[];
  brand_building_basics: string;
  mvp_suggestion: string;
  market_validation_codes: string[];
}

export interface BrandingBoost {
  name_suggestions: string[];
  tagline_options: string[];
  brand_story: string;
  logo_concept: string;
}

export interface HistoricalComparison {
  company_name: string;
  outcome: 'Success' | 'Failure' | 'Pivot';
  lesson: string;
}

export interface Shark {
  name: 'Mark Cuban' | 'Barbara Corcoran' | 'Kevin O\'Leary' | 'Lori Greiner';
  reaction: string;
  score: number;
  decision: "I'm in" | "I'm out";
  offer?: string;
  focus_area: string;
}

export interface SharkTankSimulation {
  sharks: Shark[];
  deal_likelihood: 'High' | 'Medium' | 'Low' | 'No chance';
}

export interface PitchDeckFeedback {
    critique: string;
    vc_readiness: 'Ready' | 'Almost' | 'Needs work';
}

export type Verdict = 'Proceed' | 'Proceed with Caution' | 'Do Not Pursue';
export type RiskLevel = 'Low' | 'Medium' | 'High';

export interface ValidationResult {
  // Summary Card fields
  identified_model: string;
  model_reason: string;
  final_score: number;
  verdict: Verdict;
  risk_level: RiskLevel;
  key_risks: string[];
  actionable_improvement: string;

  // Existing fields
  idea_summary: string;
  market_research: MarketResearch;
  execution_foundations: ExecutionFoundations;
  branding_boost: BrandingBoost;
  historical_comparison: HistoricalComparison[];
  shark_tank_simulation: SharkTankSimulation;
  pivoted_ideas?: string[]; // Section 7
  pitch_deck_feedback?: PitchDeckFeedback; // Section 8
  shareable_summary: string; // Section 9
}

import { GoogleGenAI, Type } from "@google/genai";
import { type ValidationResult } from '../types';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

const responseSchema = {
    type: Type.OBJECT,
    properties: {
        // Summary Card fields
        identified_model: { type: Type.STRING, description: "The business model type (e.g. SaaS, Marketplace)." },
        model_reason: { type: Type.STRING, description: "Why this model fits." },
        final_score: { type: Type.NUMBER, description: "Overall viability score out of 10." },
        verdict: { type: Type.STRING, enum: ["Proceed", "Proceed with Caution", "Do Not Pursue"] },
        risk_level: { type: Type.STRING, enum: ["Low", "Medium", "High"] },
        key_risks: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Top 3 risks." },
        actionable_improvement: { type: Type.STRING, description: "One major thing to improve immediately." },

        // Existing fields
        idea_summary: { type: Type.STRING, description: "1-2 clear sentences restating the idea." },
        market_research: {
            type: Type.OBJECT,
            properties: {
                market_demand: { type: Type.STRING, description: "Size, trends, and growth signals (max 5 lines)." },
                problem_and_pain_points: { type: Type.STRING, description: "How acute is the problem? Who feels it most? (max 5 lines)." },
                competition: { type: Type.STRING, description: "List 3-5 competitors with names and strengths." },
                suggested_usps: { type: Type.ARRAY, items: { type: Type.STRING }, description: "4-6 unique selling points." },
            },
            required: ["market_demand", "problem_and_pain_points", "competition", "suggested_usps"]
        },
        execution_foundations: {
            type: Type.OBJECT,
            properties: {
                first_3_steps: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Concrete, actionable next moves." },
                brand_building_basics: { type: Type.STRING, description: "Tone, target audience, positioning." },
                mvp_suggestion: { type: Type.STRING, description: "Minimal viable product definition + key features." },
                market_validation_codes: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Quick ways to test demand (landing page, waitlist, etc)." },
            },
            required: ["first_3_steps", "brand_building_basics", "mvp_suggestion", "market_validation_codes"]
        },
        branding_boost: {
            type: Type.OBJECT,
            properties: {
                name_suggestions: { type: Type.ARRAY, items: { type: Type.STRING }, description: "5 short, memorable names." },
                tagline_options: { type: Type.ARRAY, items: { type: Type.STRING }, description: "3 tagline options." },
                brand_story: { type: Type.STRING, description: "3-4 sentences for an About page." },
                logo_concept: { type: Type.STRING, description: "Simple text-based idea." },
            },
            required: ["name_suggestions", "tagline_options", "brand_story", "logo_concept"]
        },
        historical_comparison: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    company_name: { type: Type.STRING },
                    outcome: { type: Type.STRING, enum: ["Success", "Failure", "Pivot"] },
                    lesson: { type: Type.STRING },
                },
                required: ["company_name", "outcome", "lesson"]
            },
            description: "Compare to 2-3 real startups."
        },
        shark_tank_simulation: {
            type: Type.OBJECT,
            properties: {
                sharks: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            name: { type: Type.STRING, enum: ["Mark Cuban", "Barbara Corcoran", "Kevin O'Leary", "Lori Greiner"] },
                            reaction: { type: Type.STRING },
                            score: { type: Type.NUMBER },
                            decision: { type: Type.STRING, enum: ["I'm in", "I'm out"] },
                            offer: { type: Type.STRING },
                            focus_area: { type: Type.STRING },
                        },
                        required: ["name", "reaction", "score", "decision", "focus_area"]
                    }
                },
                deal_likelihood: { type: Type.STRING, enum: ["High", "Medium", "Low", "No chance"] },
            },
            required: ["sharks", "deal_likelihood"]
        },
        pivoted_ideas: { type: Type.ARRAY, items: { type: Type.STRING }, description: "3 alternative ideas if the main idea needs major help. Can be empty if idea is strong." },
        pitch_deck_feedback: {
            type: Type.OBJECT,
            properties: {
                critique: { type: Type.STRING },
                vc_readiness: { type: Type.STRING, enum: ["Ready", "Almost", "Needs work"] },
            },
            description: "Only populate if the input looks like a pitch or includes slide content."
        },
        shareable_summary: { type: Type.STRING, description: "One-Click Shareable Summary for Twitter/LinkedIn." },
    },
    required: [
        "identified_model", "model_reason", "final_score", "verdict", "risk_level", "key_risks", "actionable_improvement",
        "idea_summary", "market_research", "execution_foundations", "branding_boost", "historical_comparison", "shark_tank_simulation", "shareable_summary"
    ]
};

const systemInstruction = `You are BuildIT — the ultimate AI co-founder for early-stage startup ideas.

Tagline: "Validate fast. Build smart. Launch strong."

Your mission is to help founders turn raw ideas into viable startups with brutal honesty, creativity, and actionable steps. Always be encouraging yet realistic — founders need truth wrapped in motivation.

Response Style:
- Talk like a sharp, experienced co-founder having a late-night chat over coffee — casual, direct, no fluff.
- Use simple language, short sentences, and natural flow.
- Feel human, not AI.
- Deep black/dark mode friendly aesthetics in your structure.

When a user shares a startup idea, respond in the exact structured JSON format provided. 
If the input looks like a pitch deck (e.g. "Slide 1: ..."), populate the 'pitch_deck_feedback' section. Otherwise, leave it null.
If the idea has fatal flaws, populate 'pivoted_ideas'.

Output Requirement:
Return ONLY the JSON.`;


export const validateStartupIdea = async (idea: string): Promise<ValidationResult> => {
  const prompt = `Here is the startup idea/input: "${idea}"\n\nPlease analyze it.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema,
        temperature: 0.5,
      },
    });

    const jsonText = response.text.trim();
    const result = JSON.parse(jsonText);

    // Basic validation
    if (!result.idea_summary || !result.market_research) {
        throw new Error("Invalid JSON structure received from API.");
    }

    return result as ValidationResult;
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    if(error instanceof Error && error.message.includes('JSON')){
        throw new Error("Invalid JSON structure received from API.");
    }
    throw new Error("Failed to get validation from AI service.");
  }
};

