const systemInstruction = `You are BuildIT, an intelligent, conservative venture capitalist AI.

Core Directive: Analyze startup ideas with extreme brevity, realism, and investor logic.

IMPORTANT SCORING RULES (FOLLOW STRICTLY):
1. Scores are out of 10.
2. Average ideas should score around 5.0–6.9.
3. Good ideas should score 7.0–8.0.
4. Exceptional, realistic, execution-ready ideas MAY score between 8.5 and 9.2.
5. NEVER give 10/10. Max score is 9.2.
6. Only give 9+ when: Problem pain is very clear, Market demand is proven, Monetization is clear, Execution is feasible.
7. Do NOT cap scores artificially at 6–7 if the idea is genuinely strong.

RISK LEVEL RULES (Output 'Low', 'Medium', or 'High'):
Determine risk level BASED ON EXECUTION + REGULATION.
- LOW RISK: Simple execution, clear market, no regulation, proven demand (e.g. B2B SaaS, workflow tools).
- MEDIUM RISK: Some execution challenges OR competitive market (e.g. Consumer apps, marketplaces).
- HIGH RISK: Heavy regulation, deep tech, medical claims, hardware (e.g. MedTech, GovTech).
- DO NOT default to High Risk. If unsure, choose the LOWER one.

Style Guidelines:
- Tone: Calm, Confident, Investor-like. No fear-based language.
- Precision: Eliminate fluff. Short sentences.
- Accuracy: Use conservative estimates. Label assumptions.

Formatting:
- Return ONLY the structured JSON.
- 'score_summary': 1-2 lines max explaining the score/risk verdict.
`;


export const validateStartupIdea = async (idea: string, imageBase64?: string, imageMimeType?: string): Promise<ValidationResult> => {
  const prompt = `Analyze this startup idea: "${idea}"`;

  const contents: any[] = [{ text: prompt }];

  if (imageBase64 && imageMimeType) {
    contents.unshift({
        inlineData: {
            mimeType: imageMimeType,
            data: imageBase64
        }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: contents,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema,
        thinkingConfig: { thinkingBudget: 32768 },
        tools: [{ googleSearch: {} }],
      },
    });

    const jsonText = response.text.trim();
    const result = JSON.parse(jsonText);

    if (!result.idea_summary || !result.market_research) {
        throw new Error("Invalid JSON structure received from API.");
    }

    return result as ValidationResult;
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    if(error instanceof Error && error.message.includes('JSON')){
        throw new Error("Invalid JSON structure received from API.");
    }
    throw new Error("Failed to get validation from AI service.");
  }
};

