        setTimeout(() => setCopied(false), 2000);
    };

    return (
        <div className="mt-20 p-8 bg-black border border-zinc-800 rounded relative group hover:border-zinc-700 transition-colors">
            <h3 className="text-zinc-600 text-[10px] font-bold uppercase tracking-widest mb-6">Summary</h3>
            <p className="text-zinc-300 whitespace-pre-wrap font-mono text-xs leading-relaxed opacity-90">{summary}</p>
            <button
                onClick={handleCopy}
                className="absolute top-8 right-8 text-zinc-600 hover:text-white text-[10px] uppercase font-bold tracking-widest transition-colors"
            >
                {copied ? 'COPIED' : 'COPY'}
            </button>
        </div>
    );
};


