import { GoogleGenAI, Type } from "@google/genai";
import { type ValidationResult, type GeneratedIdea } from '../types';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

const DICE_TRIGGERS = [
  '🎲',
  'dice',
  'random idea',
  'surprise me',
  'give me an idea',
  'roll dice',
  'random startup',
  'idea dice'
];

// --- Validation Logic ---

const validationResponseSchema = {
    type: Type.OBJECT,
    properties: {
        confidence_score: { type: Type.NUMBER, description: "0-100 score. Be conservative." },
        kill_or_proceed_warning: { type: Type.STRING, description: "Blunt, direct verdict. No fluff." },
        criteria_scores: {
            type: Type.OBJECT,
            properties: {
                market_timing: { type: Type.NUMBER, description: "1-10" },
                product_value: { type: Type.NUMBER, description: "1-10" },
                execution_feasibility: { type: Type.NUMBER, description: "1-10" },
                competition_risk: { type: Type.NUMBER, description: "1-10 (10 is Low Risk/Good, 1 is High Risk/Bad)" },
                monetization_potential: { type: Type.NUMBER, description: "1-10" }
            },
            required: ["market_timing", "product_value", "execution_feasibility", "competition_risk", "monetization_potential"]
        },
        swot_analysis: {
            type: Type.OBJECT,
            properties: {
                strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
                weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
                opportunities: { type: Type.ARRAY, items: { type: Type.STRING } },
                threats: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ["strengths", "weaknesses", "opportunities", "threats"]
        },
        business_model_canvas: {
            type: Type.OBJECT,
            properties: {
                value_propositions: { type: Type.STRING, description: "Concise summary." },
                customer_segments: { type: Type.STRING, description: "Concise summary." },
                revenue_streams: { type: Type.STRING, description: "Concise summary." },
                cost_structure: { type: Type.STRING, description: "Concise summary." }
            },
            required: ["value_propositions", "customer_segments", "revenue_streams", "cost_structure"]
        },
        traction_simulator_18mo: { type: Type.STRING, description: "A Markdown table string using pipes (|) for Month 6, 12, 18 projections of Revenue and Users." },
        cost_rough_estimate: { type: Type.STRING, description: "Estimated monthly burn rate range (e.g. $2k - $5k)." },
        gtm_plan: {
            type: Type.OBJECT,
            properties: {
                timeline_estimator_5_weeks: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Week 1 to Week 5 high level tasks." },
                first_10_customers_strategy: { type: Type.STRING, description: "Specific tactic to get first 10 paying users." }
            },
            required: ["timeline_estimator_5_weeks", "first_10_customers_strategy"]
        },
        idea_pivot_suggestions: { type: Type.ARRAY, items: { type: Type.STRING }, description: "2-3 Pivot ideas if score < 55. Else empty." },
        industry_benchmark_comparison: { type: Type.STRING, description: "1 sentence comparing to industry average." }
    },
    required: [
        "confidence_score",
        "kill_or_proceed_warning",
        "criteria_scores",
        "swot_analysis",
        "business_model_canvas",
        "traction_simulator_18mo",
        "cost_rough_estimate",
        "gtm_plan",
        "industry_benchmark_comparison"
    ]
};

const validationSystemInstruction = `You are BuildIT AI, a Brutally Honest, highly experienced Venture Capitalist and hands-on Product Manager.
Your goal is to give the founder the hard truth and a pragmatic path forward.

CORE OBJECTIVES:
1. Honesty & Confidence: Generate a numerical confidence_score (0-100). Be strict. Most ideas are 40-60.
2. Strategic Modeling: Generate a SWOT analysis and a summary of the Business Model Canvas (BMC).
3. Financial Reality: Create a simple text table for traction_simulator_18mo and a cost_rough_estimate.
4. Actionable Plan: Generate a GTM plan with a 5-week timeline.
5. Pivot Analysis: If score < 55, provide specific pivots.

TONE & RULES:
- Brutally Honest, Direct, Practical, Data-Driven.
- Do NOT use comforting language.
- "competition_risk": Score 1-10. 1 = Extreme Competition (Bad), 10 = Blue Ocean (Good).
- "traction_simulator_18mo": Format as a clean text table with headers: | Metric | Month 6 | Month 12 | Month 18 |.
`;

export const validateStartupIdea = async (idea: string, imageBase64?: string, imageMimeType?: string): Promise<ValidationResult> => {
  const normalizedIdea = idea.trim().toLowerCase();
  const isDiceRoll = DICE_TRIGGERS.includes(normalizedIdea);

  let prompt = `Analyze this startup idea: "${idea}"`;

  if (isDiceRoll) {
      prompt = `
      ACT AS A STARTUP GENERATOR.

      TASK:
      1. Generate a completely NEW, high-potential startup idea specifically for the Indian Market in 2025.
      2. Trends to leverage: UPSC/NEET/JEE Prep, Hyper-local services (Tier-2/3), SMB SaaS tools, Quick Commerce, WhatsApp Commerce, Creator Economy (Instagram/Reels).
      3. The idea MUST be strong enough to score 8.0-9.5/10 on your strict validation criteria.
      4. Describe the idea clearly (Problem, Solution, USP).

      THEN:
      Analyze this generated idea as BuildIT AI (Brutally Honest VC).
      Fill the JSON schema completely for this new idea.
      - 'idea_summary': A compelling 1-sentence pitch of this new idea.
      - 'confidence_score': Should be high (80-95).
      - 'kill_or_proceed_warning': "PROCEED" (with specific aggressive advice).
      `;
  }

  const contents: any[] = [{ text: prompt }];

  if (!isDiceRoll && imageBase64 && imageMimeType) {
    contents.unshift({
        inlineData: {
            mimeType: imageMimeType,
            data: imageBase64
        }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: contents,
      config: {
        systemInstruction: validationSystemInstruction,
        responseMimeType: "application/json",
        responseSchema: validationResponseSchema,
        thinkingConfig: { thinkingBudget: 32768 },
      },
    });

    const jsonText = response.text.trim();
    const result = JSON.parse(jsonText);

    if (typeof result.confidence_score !== 'number' || !result.kill_or_proceed_warning) {
        throw new Error("Invalid JSON structure received from API.");
    }

    return result as ValidationResult;
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    if(error instanceof Error && error.message.includes('JSON')){
        throw new Error("Invalid JSON structure received from API.");
    }
    throw new Error("Failed to get validation from AI service.");
  }
};


// --- Generator Logic (Dice Roll) ---

const generatorSystemInstruction = `You are **BuildIT Idea Generator**, a creative and strategic engine. Your sole function is to generate one novel, actionable startup idea based on the intersection of a niche industry and an emerging technology.

**OUTPUT RULE:** You must return a single, complete JSON object.`;

const generatorResponseSchema = {
    type: Type.OBJECT,
    properties: {
        generated_idea_name: {
            type: Type.STRING,
            description: "A clever, unique name for the startup idea."
        },
        generated_idea_description: {
            type: Type.STRING,
            description: "One compelling sentence describing the high-value problem and the innovative solution."
        },
        suggested_market_code: {
            type: Type.STRING,
            description: "A single word for the market niche (e.g., PropTech, EdTech, FinTech, GovTech)."
        }
    },
    required: ["generated_idea_name", "generated_idea_description", "suggested_market_code"]
};

export const generateRandomIdea = async (): Promise<GeneratedIdea> => {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-pro-preview",
            contents: "Generate a novel startup idea now.",
            config: {
                systemInstruction: generatorSystemInstruction,
                responseMimeType: "application/json",
                responseSchema: generatorResponseSchema,
            },
        });

        const jsonText = response.text.trim();
        return JSON.parse(jsonText) as GeneratedIdea;
    } catch (error) {
        console.error("Error generating random idea:", error);
        throw new Error("Failed to generate idea.");
    }
};

