export const IdeaForm: React.FC<IdeaFormProps> = ({ idea, setIdea, onValidate, isLoading }) => {
  const [selectedImage, setSelectedImage] = useState<File | undefined>(undefined);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onValidate(selectedImage);
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setSelectedImage(file);
      const url = URL.createObjectURL(file);
      setPreviewUrl(url);
    }
  };

  const clearImage = () => {
    setSelectedImage(undefined);
    setPreviewUrl(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleDiceRoll = async () => {
    setIsGenerating(true);
    try {
        const result = await generateRandomIdea();
        // The result contains { generated_idea_name, generated_idea_description, suggested_market_code }
        // We populate the input with the description as requested.
        setIdea(result.generated_idea_description);
    } catch (e) {
        console.error("Failed to generate idea", e);
    } finally {
        setIsGenerating(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      <div className="space-y-4">
        <div className="flex justify-between items-center">
            <label htmlFor="startup-idea" className="block text-sm font-medium text-zinc-500 uppercase tracking-wide">
              What are we building?
            </label>
            <button
                type="button"
                onClick={handleDiceRoll}
                disabled={isGenerating || isLoading}
                className="flex items-center gap-2 text-xs text-cyan-500 hover:text-cyan-400 font-mono uppercase tracking-widest transition-colors disabled:opacity-50 disabled:cursor-not-allowed group active:scale-95 duration-75 ease-out"
            >
                <DiceIcon className={`transition-transform duration-500 ${isGenerating ? "animate-spin" : "group-hover:rotate-180"}`} />
                <span>{isGenerating ? "Rolling..." : "Surprise Me"}</span>
            </button>
        </div>
        <div className="relative group">
            <textarea
              id="startup-idea"
              rows={6}
              value={idea}
              onChange={(e) => setIdea(e.target.value)}
              placeholder="e.g. Uber for dog walking but exclusively for corgis..."
              className="w-full bg-black border border-zinc-800 rounded-sm p-4 text-white placeholder-zinc-700 
                focus:outline-none focus:border-cyan-400 focus:shadow-[0_0_15px_rgba(34,211,238,0.15)] 
                transition-all duration-150 font-light"
              required
            />

            <div className="absolute bottom-3 right-3">
                 <input 
                    type="file" 
                    id="image-upload" 
                    accept="image/*" 
                    onChange={handleImageChange} 
                    className="hidden"
                    ref={fileInputRef}
                  />
                  <label 
                    htmlFor="image-upload" 
                    className="cursor-pointer flex items-center gap-2 text-zinc-500 hover:text-white transition-colors bg-zinc-900/80 p-2 rounded-full border border-zinc-800 backdrop-blur-sm"
                    title="Attach a sketch or diagram"
                  >
                    <ImageIcon />
                  </label>
            </div>
        </div>

        {previewUrl && (
          <div className="relative inline-block mt-2 animate-fade-in">
            <img src={previewUrl} alt="Preview" className="h-24 w-auto rounded border border-zinc-700 object-cover" />
            <button
              type="button"
              onClick={clearImage}
              className="absolute -top-2 -right-2 bg-zinc-800 text-white rounded-full p-1 border border-zinc-600 hover:bg-zinc-700"
            >
              <XIcon />
            </button>
            <p className="text-xs text-zinc-500 mt-1">Image attached</p>
          </div>
        )}
      </div>

      <div>
        <button
          type="submit"
          disabled={isLoading || isGenerating}
          className="w-full flex justify-center items-center bg-white text-black font-bold py-4 px-6 rounded-sm text-lg 
            hover:bg-cyan-50 hover:shadow-[0_0_10px_rgba(255,255,255,0.3)]
            active:scale-[0.98] active:brightness-110 
            transition-all duration-75 ease-out
            disabled:bg-zinc-800 disabled:text-zinc-600 disabled:cursor-not-allowed disabled:transform-none disabled:shadow-none tracking-tight"
        >
          {isLoading ? 'ANALYZING...' : 'VALIDATE IDEA'}
        </button>
      </div>
    </form>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { type ValidationResult, type GeneratedIdea } from '../types';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

const DICE_TRIGGERS = [
  '🎲',
  'dice',
  'random idea',
  'surprise me',
  'give me an idea',
  'roll dice',
  'random startup',
  'idea dice'
];

// --- Validation Logic ---

const validationResponseSchema = {
    type: Type.OBJECT,
    properties: {
        confidence_score: { type: Type.NUMBER, description: "0-10 score (e.g. 7.2). This is the final verdict average." },
        kill_or_proceed_warning: { type: Type.STRING, description: "Blunt, direct verdict. No fluff." },
        criteria_scores: {
            type: Type.OBJECT,
            properties: {
                market_timing: { type: Type.NUMBER, description: "1-10" },
                product_value: { type: Type.NUMBER, description: "1-10" },
                execution_feasibility: { type: Type.NUMBER, description: "1-10" },
                competition_risk: { type: Type.NUMBER, description: "1-10 (10 is Low Risk/Good, 1 is High Risk/Bad)" },
                monetization_potential: { type: Type.NUMBER, description: "1-10" }
            },
            required: ["market_timing", "product_value", "execution_feasibility", "competition_risk", "monetization_potential"]
        },
        swot_analysis: {
            type: Type.OBJECT,
            properties: {
                strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
                weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
                opportunities: { type: Type.ARRAY, items: { type: Type.STRING } },
                threats: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ["strengths", "weaknesses", "opportunities", "threats"]
        },
        business_model_canvas: {
            type: Type.OBJECT,
            properties: {
                value_propositions: { type: Type.STRING, description: "Concise summary." },
                customer_segments: { type: Type.STRING, description: "Concise summary." },
                revenue_streams: { type: Type.STRING, description: "Concise summary." },
                cost_structure: { type: Type.STRING, description: "Concise summary." }
            },
            required: ["value_propositions", "customer_segments", "revenue_streams", "cost_structure"]
        },
        traction_simulator_18mo: { type: Type.STRING, description: "A Markdown table string using pipes (|) for Month 6, 12, 18 projections of Revenue and Users." },
        cost_rough_estimate: { type: Type.STRING, description: "Estimated monthly burn rate range (e.g. $2k - $5k)." },
        gtm_plan: {
            type: Type.OBJECT,
            properties: {
                timeline_estimator_5_weeks: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Week 1 to Week 5 high level tasks." },
                first_10_customers_strategy: { type: Type.STRING, description: "Specific tactic to get first 10 paying users." }
            },
            required: ["timeline_estimator_5_weeks", "first_10_customers_strategy"]
        },
        idea_pivot_suggestions: { type: Type.ARRAY, items: { type: Type.STRING }, description: "2-3 Pivot ideas if score < 5.5. Else empty." },
        industry_benchmark_comparison: { type: Type.STRING, description: "1 sentence comparing to industry average." }
    },
    required: [
        "confidence_score",
        "kill_or_proceed_warning",
        "criteria_scores",
        "swot_analysis",
        "business_model_canvas",
        "traction_simulator_18mo",
        "cost_rough_estimate",
        "gtm_plan",
        "industry_benchmark_comparison"
    ]
};

const validationSystemInstruction = `You are **BuildIT AI**, a Senior Partner at a top-tier VC firm.

**TONE & RULES:**

1.  **Persona:** You are a senior partner at a VC firm who has seen it all—the good, the bad, and the founders who mistake confidence for competence. Your humor is dry, often undercutting, and based on objective reality. No participation trophies here.

2.  **Scoring Standard:** All scores are out of a full **10 points** (1.0 to 10.0). Think of it this way:
    * **1-3 (Catastrophe):** "This idea has the market viability of a handwritten fax. You're losing money just thinking about it."
    * **4-6 (Needs Therapy):** "It has legs, but they're broken. Requires major pivots and heavy sedation before launch."
    * **7-8 (Decent):** "A solid B+. Not revolutionary, but profitable. It's the startup equivalent of a comfortable sedan—reliable, but don't expect a parade."
    * **9-10 (Unicorn Territory):** "Stop reading this. Go build it. If you fail, it's probably your fault, not the idea's."

3.  **Output Rule:** Ensure the 'confidence_score' field in the JSON structure accurately reflects the average of the 5 pillars, using one decimal point (e.g., 7.2).

**CRITICAL FORMATTING:**
- "competition_risk": Score 1-10. 1 = Extreme Competition (Bad), 10 = Blue Ocean (Good).
- "traction_simulator_18mo": Format as a clean text table with headers: | Metric | Month 6 | Month 12 | Month 18 |.
- Fill all fields in the JSON schema based on this persona.
`;

export const validateStartupIdea = async (idea: string, imageBase64?: string, imageMimeType?: string): Promise<ValidationResult> => {
  const normalizedIdea = idea.trim().toLowerCase();
  const isDiceRoll = DICE_TRIGGERS.includes(normalizedIdea);

  let prompt = `Analyze this startup idea: "${idea}"`;

  if (isDiceRoll) {
      prompt = `
      ACT AS A STARTUP GENERATOR.

      TASK:
      1. Generate a completely NEW, high-potential startup idea specifically for the Indian Market in 2025.
      2. Trends to leverage: UPSC/NEET/JEE Prep, Hyper-local services (Tier-2/3), SMB SaaS tools, Quick Commerce, WhatsApp Commerce, Creator Economy (Instagram/Reels).
      3. The idea MUST be strong enough to score 8.0-9.5/10 on your strict validation criteria.
      4. Describe the idea clearly (Problem, Solution, USP).

      THEN:
      Analyze this generated idea as BuildIT AI (Brutally Honest VC).
      Fill the JSON schema completely for this new idea.
      - 'idea_summary': A compelling 1-sentence pitch of this new idea.
      - 'confidence_score': Should be high (8.0-9.5).
      - 'kill_or_proceed_warning': "PROCEED" (with specific aggressive advice).
      `;
  }

  const contents: any[] = [{ text: prompt }];

  if (!isDiceRoll && imageBase64 && imageMimeType) {
    contents.unshift({
        inlineData: {
            mimeType: imageMimeType,
            data: imageBase64
        }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: contents,
      config: {
        systemInstruction: validationSystemInstruction,
        responseMimeType: "application/json",
        responseSchema: validationResponseSchema,
        thinkingConfig: { thinkingBudget: 32768 },
      },
    });

    const jsonText = response.text.trim();
    const result = JSON.parse(jsonText);

    if (typeof result.confidence_score !== 'number' || !result.kill_or_proceed_warning) {
        throw new Error("Invalid JSON structure received from API.");
    }

    return result as ValidationResult;
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    if(error instanceof Error && error.message.includes('JSON')){
        throw new Error("Invalid JSON structure received from API.");
    }
    throw new Error("Failed to get validation from AI service.");
  }
};


