                        <div className={`mt-auto border-t pt-3 font-mono text-xs font-bold ${isOut ? 'text-red-500 border-red-900/30' : 'text-green-500 border-green-900/30'}`}>
                            {item.verdict}
                        </div>
                    </div>
                  );
              })}
          </div>
      ) : null}
    </div>
  );
};

