  <div className="bg-zinc-900/20 border border-zinc-800/50 p-6 rounded-sm animate-slide-up-fade" style={{ animationDelay: `${delay}ms` }}>
    <h3 className="text-lg font-bold text-white mb-4">{title}</h3>
