export const PmModeDisplay: React.FC<PmModeDisplayProps> = ({ content }) => {
  const sections = content.split('**').slice(1); // Split by bold markers, skip first empty part
  const parsedContent: { title: string; body: string }[] = [];

  for (let i = 0; i < sections.length; i += 2) {
    if (sections[i] && sections[i + 1]) {
      parsedContent.push({
        title: sections[i].trim().replace(/\n/g, ''), // Remove newlines from title
        body: sections[i + 1].trim(),
      });
    }
  }

  return (
    <div className="max-w-4xl mx-auto py-8 font-sans selection:bg-zinc-800 selection:text-white">
      <div className="text-center text-zinc-500 text-[10px] uppercase tracking-widest font-bold mb-8 animate-fade-in" style={{ animationDelay: '0ms' }}>
        Product Manager Mode Report
      </div>
      <div className="space-y-8">
        {parsedContent.map((section, index) => (
          <PmSection key={index} title={section.title} delay={100 * index}>
            {section.body.split('\n').map((line, lineIndex) => {
              if (line.match(/^\d+\./)) { // Numbered list item
                return <p key={lineIndex} className="ml-4 indent-[-1.5em]">{line}</p>;
              }
              return <p key={lineIndex}>{line}</p>;
            })}
          </PmSection>
        ))}
      </div>
    </div>
  );
};

